#include <iostream>
#include <sstream>
#include <string>
using namespace std;

int main() {
    string req = "GET /index.html HTTP/1.1";
    istringstream iss(req);
    string method, path, version;
    iss >> method >> path >> version;
    cout << "Method: " << method << endl;
    cout << "Path: " << path << endl;
    cout << "Version: " << version << endl;
    return 0;
}
